    c_editing: `<rect x="2.5" y="4" width="19" height="16" rx="2.5" fill="none" stroke="currentColor" stroke-width="1.6"/><path d="M2.5 14h19M7 14v6M12.5 14v6M17 14v6" stroke="currentColor" stroke-width="1.4"/><path d="M10 6.8v4.4l3.6-2.2z" fill="currentColor"/>`,
