    c_design: `<path d="M12 2.8l7 7-7.4 9.4-2.4-2.4L4.8 21 3 19.2l4.2-4.4-2.4-2.4z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><circle cx="12.3" cy="10" r="1.6" fill="currentColor"/><path d="M14.5 21h6.5" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/>`,
    c_3d: `<path d="M12 2.8l8 4.6v9.2l-8 4.6-8-4.6V7.4z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><path d="M4 7.4l8 4.6 8-4.6M12 12v9.2" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/>`,
