    ["#8cffd2", "#2fb98a"], ["#ffc29a", "#e2724a"], ["#7ab8ff", "#2f6fd6"], ["#ffe48a", "#d6a52a"],
    ["#ff9a9a", "#c94a5a"], ["#c8ff8a", "#6fb92f"]
