  const PAL_LIGHT = [
    ["#4FB3E8", "#1f7fb8"], ["#ff6f9f", "#c2386b"], ["#1b3765", "#0d1f3d"], ["#8a6cff", "#5a3fd0"],
    ["#2fd39a", "#14895f"], ["#ff9a5c", "#cf5f26"], ["#3d8bff", "#1d58c9"], ["#FFC83D", "#c9940f"],
    ["#ff6b6b", "#c23c4c"], ["#79c93a", "#468f17"]
  ];
  const pal = () => (theme === "light" ? PAL_LIGHT : PAL_DARK);
  const rand = (a, b) => a + Math.random() * (b - a);
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const eIO = (x) => x < .5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  const eOut = (x) => 1 - Math.pow(1 - x, 3);
  const mouse = { x: W * 0.62, y: H * 0.45, px: W * 0.62, py: H * 0.45, active: false };
