  function drawPointer(x, y, ang, s, col, alpha) {
    drawArrow(x - Math.cos(ang) * s * 1.25, y - Math.sin(ang) * s * 1.25, ang, s, col, alpha);
  }
  function drawPlus(x, y, s, alpha, color, rot) {
    ctx.save(); ctx.globalAlpha = alpha; if (rot) { ctx.translate(x, y); ctx.rotate(rot); ctx.translate(-x, -y); } ctx.strokeStyle = color; ctx.lineWidth = 1.6; ctx.lineCap = "round";
    ctx.beginPath(); ctx.moveTo(x - s, y); ctx.lineTo(x + s, y); ctx.moveTo(x, y - s); ctx.lineTo(x, y + s); ctx.stroke(); ctx.restore();
  }
