      const ang = Math.atan2(mouse.y - mouse.py, mouse.x - mouse.px) + Math.PI + rand(-0.9, 0.9);
      const sp = rand(0.6, 2.4);
      if (Math.random() < 0.3) bits.push({ t: "plus", x: x + rand(-14, 14), y: y + rand(-14, 14), vx: Math.cos(ang) * sp * 0.4, vy: Math.sin(ang) * sp * 0.4 - 0.2, life: 1, decay: rand(0.012, 0.025), s: rand(3, 6) });
      else bits.push({ t: "arrow", x, y, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp, rot: rand(0, 6.28), vr: rand(-0.08, 0.08), life: 1, decay: rand(0.012, 0.022), s: rand(4, 8), ci: (Math.random() * 10) | 0 });
