    // safety net for very fast scrolling: sections that are fully above the fold are snapped to built
    if (!reduceMotion && !snapping) for (const s of director.secs) if (!s.done && s !== HERO && s.root.getBoundingClientRect().bottom < 0) director.pass(s);
